\section{Introduction}

\subsection{The problem}
A lossless code for a finite message set $X$ is, up to integrality, a probability distribution $q$ on $X$: encoding $x$ costs $\log_2 (1/q(x))$ bits. A compressor with perfect knowledge of the source $p$ would use $q = p$ and pay the entropy $H(p)$.

Real compressors lack that knowledge. They face a whole \emph{class} of candidate sources $\mathcal S = \{p_\theta : \theta \in \Theta\}$ and are judged by \emph{regret} relative to the best member in hindsight,
\[
R(q,x) = \log_2 \frac{1}{q(x)} - \log_2 \frac{1}{\hat p_{\mathcal S}(x)}, \qquad \hat p_{\mathcal S}(x) := \sup_{\theta \in \Theta} p_\theta(x),
\]
where $\hat p_{\mathcal S}$ is the \emph{maximum-likelihood envelope}: the largest probability any model in the class assigns to the message $x$. The envelope is generally not a probability distribution; its total mass
\[
C_{\mathcal S} := \sum_{x \in X} \hat p_{\mathcal S}(x)
\]
is the \emph{Shtarkov sum}. Normalising the envelope produces the normalized maximum likelihood distribution $q_{\mathrm{NML}} = \hat p_{\mathcal S}/C_{\mathcal S}$, whose regret is the constant $\log_2 C_{\mathcal S}$ for \emph{every} message; no code does better in the worst case. We therefore call
\[
\price(\mathcal S) := \log_2 C_{\mathcal S} \ \text{bits}
\]
the \emph{price of universality} of the class.

Earlier work in this line settled the qualitative behaviour: $C_{\mathcal S} = 1$ exactly when the class is degenerate (a single distribution dominates every member pointwise), so any genuinely new source makes the price strictly positive; and the price is monotone under enlargement of the class.

\subsection{Contribution}
We answer the quantitative question --- how many bits does one more model cost? --- exactly (Theorem~\ref{thm:marginal}), and derive from the answer that the price of universality, as a functional on \emph{libraries} of models, is a monotone submodular set function, additively (Theorem~\ref{thm:submod}), multiplicatively (Theorem~\ref{thm:mulsubmod}) and, under a positivity guard, in bits (Theorem~\ref{thm:bitsubmod}). The payoff is a design theorem: greedy library construction is $(1-1/e)$-optimal (Theorem~\ref{thm:greedy}), i.e.\ within two-thirds of a bit of an optimum whose exact computation requires exhaustive search.

\subsection{Two readings of one number}
The same quantity plays two roles. If a class is \emph{imposed} on you, $\log_2 C_{\mathcal S}$ is a cost and you want it small. If a library is \emph{chosen} from a pool, $C(A)$ measures the probability mass the envelope captures --- the library's explanatory reach --- and you want it large subject to a budget. The mathematics is identical; only the direction of preference differs.

\section{Setup}

Throughout, $X$ is a finite nonempty set and $(t)^{+} = \max(t,0)$.

\begin{definition}[Source class]
A \emph{source class} on $X$ with parameter set $\Theta$ is a family $(p_\theta)_{\theta \in \Theta}$ of functions $p_\theta : X \to \mathbb R$ with $p_\theta \ge 0$ and $\sum_{x} p_\theta(x) = 1$ for each $\theta$. The parameter set may be infinite.
\end{definition}

\begin{definition}[Envelope, Shtarkov sum, price]
For a nonempty class, $\hat p_{\mathcal S}(x) = \sup_\theta p_\theta(x)$, $C_{\mathcal S} = \sum_x \hat p_{\mathcal S}(x)$ and $\price(\mathcal S) = \log_2 C_{\mathcal S}$.
\end{definition}

Since $p_\theta \le \hat p_{\mathcal S} \le 1$ pointwise, every nonempty class satisfies $1 \le C_{\mathcal S} \le |X|$, so $0 \le \price(\mathcal S) \le \log_2|X|$ and all logarithms below are defined.

\begin{definition}[Total variation]
For distributions $p,q$ on $X$, $\|p-q\|_{\TV} = \tfrac12\sum_x |p(x)-q(x)|$.
\end{definition}

\begin{lemma}[Positive part identity]\label{lem:pos}
For all real $a,b$: $\max(a,b) - b = (a-b)^{+}$.
\end{lemma}
\begin{proof}
If $a \le b$ both sides vanish; if $b \le a$ both equal $a - b$.
\end{proof}

\section{The marginal value of a model}

Let $\mathcal S$ be a nonempty class and $p$ a distribution on $X$; write $\mathcal S \cup \{p\}$ for the class enlarged by $p$.

\begin{lemma}[Envelope of an enlarged class]\label{lem:envadd}
$\widehat{p_{\mathcal S \cup \{p\}}}(x) = \max\bigl(p(x), \hat p_{\mathcal S}(x)\bigr)$ for all $x$.
\end{lemma}
\begin{proof}
Every member of the enlarged class lies below the right-hand side, giving ``$\le$''; conversely $p(x)$ and each $p_\theta(x)$ lie below the enlarged envelope, hence so does $\hat p_{\mathcal S}(x)$, giving ``$\ge$''. Attainment of the suprema is never used.
\end{proof}

\begin{theorem}[Marginal value formula]\label{thm:marginal}
For every nonempty class $\mathcal S$ and distribution $p$ on $X$,
\[
C_{\mathcal S \cup \{p\}} \;=\; C_{\mathcal S} \;+\; \sum_{x \in X} \bigl(p(x) - \hat p_{\mathcal S}(x)\bigr)^{+}.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:envadd} and Lemma~\ref{lem:pos}, pointwise
$\max(p(x),\hat p_{\mathcal S}(x)) = \hat p_{\mathcal S}(x) + (p(x) - \hat p_{\mathcal S}(x))^{+}$;
sum over the finite set $X$.
\end{proof}

Thus one pays only for the mass on which the newcomer beats the incumbent envelope.

\begin{corollary}[Nonnegativity]
$C_{\mathcal S} \le C_{\mathcal S \cup \{p\}}$: enlarging a class never lowers the price.
\end{corollary}

\begin{corollary}[Free models]\label{cor:free}
$C_{\mathcal S \cup \{p\}} = C_{\mathcal S}$ if and only if $p(x) \le \hat p_{\mathcal S}(x)$ for all $x$.
\end{corollary}
\begin{proof}
A finite sum of nonnegative terms vanishes iff each term does, and $(p(x)-\hat p_{\mathcal S}(x))^{+} = 0$ iff $p(x) \le \hat p_{\mathcal S}(x)$.
\end{proof}

\begin{corollary}[Genuinely new models]
$C_{\mathcal S} < C_{\mathcal S\cup\{p\}}$ iff $\hat p_{\mathcal S}(x) < p(x)$ for some $x$; equivalently, in bits, $\price(\mathcal S) < \price(\mathcal S \cup \{p\})$ iff the new model outbids the envelope somewhere.
\end{corollary}
\begin{proof}
The first assertion is Corollary~\ref{cor:free} together with monotonicity; the second follows since $\log_2$ is strictly increasing and both sums are at least $1$.
\end{proof}

\begin{proposition}[Bounds on the increment]
$C_{\mathcal S\cup\{p\}} - C_{\mathcal S} \le \sum_x |p(x)-\hat p_{\mathcal S}(x)|$ and $C_{\mathcal S\cup\{p\}} - C_{\mathcal S} \le 1$.
\end{proposition}
\begin{proof}
$(t)^{+} \le |t|$ gives the first. For the second, $(p(x)-\hat p_{\mathcal S}(x))^{+} \le p(x)$ since $\hat p_{\mathcal S} \ge 0$; summing gives $1$.
\end{proof}

\begin{theorem}[Mixtures are free]
If $\Theta$ is finite, $w_\theta \ge 0$ with $\sum_\theta w_\theta = 1$ and $p = \sum_\theta w_\theta p_\theta$, then $C_{\mathcal S \cup \{p\}} = C_{\mathcal S}$.
\end{theorem}
\begin{proof}
$p(x) = \sum_\theta w_\theta p_\theta(x) \le \sum_\theta w_\theta \hat p_{\mathcal S}(x) = \hat p_{\mathcal S}(x)$; apply Corollary~\ref{cor:free}.
\end{proof}

Hence the price of universality is blind to the convex hull: only extreme points matter.

\subsection{Merging whole classes}

\begin{theorem}[Envelope and price of a union]
For nonempty classes $\mathcal S, \mathcal T$ on $X$ with disjoint union $\mathcal S \sqcup \mathcal T$,
\[
\widehat{p_{\mathcal S \sqcup \mathcal T}} = \max(\hat p_{\mathcal S}, \hat p_{\mathcal T}), \qquad
C_{\mathcal S \sqcup \mathcal T} = C_{\mathcal S} + \sum_x \bigl(\hat p_{\mathcal T}(x) - \hat p_{\mathcal S}(x)\bigr)^{+},
\]
and $C_{\mathcal S \sqcup \mathcal T} = C_{\mathcal S}$ iff $\hat p_{\mathcal T} \le \hat p_{\mathcal S}$ pointwise.
\end{theorem}
\begin{proof}
Identical to Lemma~\ref{lem:envadd} and Theorem~\ref{thm:marginal} with $\hat p_{\mathcal T}$ in place of $p$; neither proof used $\sum_x p(x) = 1$.
\end{proof}

\begin{theorem}[Antitonicity of marginal value]
If $\hat p_{\mathcal S} \le \hat p_{\mathcal S'}$ pointwise then for every class $\mathcal T$,
$\sum_x (\hat p_{\mathcal T}(x)-\hat p_{\mathcal S'}(x))^{+} \le \sum_x (\hat p_{\mathcal T}(x)-\hat p_{\mathcal S}(x))^{+}$.
\end{theorem}
\begin{proof}
$t \mapsto (c-t)^{+}$ is antitone; apply pointwise and sum.
\end{proof}

This is diminishing returns in complete generality. The rest of the paper recasts it as a statement about set functions, where the algorithmic consequences live.

\section{The library price functional}

Fix a \emph{pool} of candidate models $P_i : X \to \mathbb R$ indexed by $i \in \iota$; \emph{libraries} are finite subsets $A \subseteq \iota$. Except where stated, the $P_i$ need not be distributions.

\begin{definition}[Library envelope and price functional]
$\env_A(x) = \max\bigl(\{0\}\cup\{P_i(x) : i \in A\}\bigr)$, so $\env_\emptyset = 0$; and
\[
C(A) = \sum_{x \in X} \env_A(x), \qquad \price(A) = \log_2 C(A) \ \ (\text{when } C(A) > 0).
\]
\end{definition}

\begin{lemma}[Envelope calculus]\label{lem:envcalc}
For libraries $A, B$, $j \in \iota$ and $x \in X$:
(i) $\env_A(x) \ge 0$;
(ii) $P_i(x) \le \env_A(x)$ for $i \in A$;
(iii) if $c \ge 0$ and $c \ge P_i(x)$ for all $i \in A$ then $c \ge \env_A(x)$;
(iv) $A \subseteq B \Rightarrow \env_A(x) \le \env_B(x)$;
(v) $\env_{A\cup\{j\}}(x) = \max(P_j(x), \env_A(x))$;
(vi) $\env_{A\cup B}(x) = \max(\env_A(x), \env_B(x))$.
\end{lemma}
\begin{proof}
(i)--(iii) are the defining properties of the maximum of a finite set augmented by $0$; (iv) follows from (ii) and (iii); (v) is idempotence of $\max$; (vi) follows from (iv) for ``$\ge$'' and from (ii)--(iii) applied separately to $A$ and $B$ for ``$\le$''.
\end{proof}

\begin{proposition}
$C(\emptyset) = 0$, $C \ge 0$, and $C$ is monotone: $A \subseteq B \Rightarrow C(A) \le C(B)$.
\end{proposition}

\begin{theorem}[Marginal value, library form]\label{thm:libmarg}
$\displaystyle \Delta(j\mid A) := C(A\cup\{j\}) - C(A) = \sum_{x \in X}\bigl(P_j(x) - \env_A(x)\bigr)^{+}$.
\end{theorem}
\begin{proof}
Lemma~\ref{lem:envcalc}(v), then Lemma~\ref{lem:pos}, summed over $x$.
\end{proof}

\begin{theorem}[Submodularity]\label{thm:submod}
$C(A\cup B) + C(A \cap B) \le C(A) + C(B)$ for all libraries $A, B$.
\end{theorem}
\begin{proof}
It suffices to prove the pointwise inequality. Put $a = \env_A(x)$, $b = \env_B(x)$, $i = \env_{A\cap B}(x)$. By Lemma~\ref{lem:envcalc}(vi) the union term is $\max(a,b)$, and by (iv) $i \le a$, $i \le b$. If $a \le b$ then $\max(a,b) + i = b + i \le b + a$; symmetrically otherwise. Sum over $x$.
\end{proof}

\begin{theorem}[Diminishing returns]\label{thm:dim}
If $A \subseteq B$ then $\Delta(j \mid B) \le \Delta(j \mid A)$ for every $j$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:libmarg} and $\env_A \le \env_B$ (Lemma~\ref{lem:envcalc}(iv)), termwise $(P_j(x)-\env_B(x))^{+} \le (P_j(x)-\env_A(x))^{+}$.
\end{proof}

\begin{theorem}[Submodular covering inequality]\label{thm:cover}
$\displaystyle C(A \cup B) - C(A) \le \sum_{j \in B} \Delta(j \mid A)$.
\end{theorem}
\begin{proof}
We prove the pointwise version by induction on $B$:
$\env_{A\cup B}(x) - \env_A(x) \le \sum_{j\in B}(P_j(x)-\env_A(x))^{+}$.
The empty case is trivial. For $B' = B \cup \{j\}$, $j \notin B$, put $e = \env_A(x)$, $u = \env_{A \cup B}(x)$, $t = (P_j(x)-e)^{+} \ge 0$ and $\Sigma = \sum_{i\in B}(P_i(x)-e)^{+}\ge 0$. Since $\env_{A\cup B'}(x) = \max(P_j(x), u)$: if $P_j(x) \le u$ the left side is $u - e \le \Sigma \le \Sigma + t$ by induction; otherwise it is $P_j(x) - e \le t \le t + \Sigma$. Summing over $x$, exchanging the two finite sums and applying Theorem~\ref{thm:libmarg} gives the claim.
\end{proof}

\subsection{Bridge to source classes}

\begin{theorem}[The library functional is a Shtarkov sum]
Suppose $P_i \ge 0$ and $\sum_x P_i(x) = 1$ for all $i$, and let $A \ne \emptyset$. Let $\mathcal S_A$ be the class whose members are the $P_i$, $i \in A$. Then $\hat p_{\mathcal S_A} = \env_A$ and hence $C_{\mathcal S_A} = C(A)$.
\end{theorem}
\begin{proof}
Both are the least upper bound of $\{P_i(x) : i \in A\}$; for $\env_A$ one uses $A \ne \emptyset$ and $P_i \ge 0$ to discard the auxiliary $0$. Sum over $x$.
\end{proof}

\begin{proposition}\label{prop:onele}
If the pool consists of genuine sources and $A \ne \emptyset$, then $C(A) \ge 1$ and $\price(A) \ge 0$.
\end{proposition}
\begin{proof}
Pick $i \in A$: $1 = \sum_x P_i(x) \le \sum_x \env_A(x) = C(A)$.
\end{proof}

\begin{theorem}[Two-model libraries]\label{thm:pair}
For sources $p,q$: $C(\{p,q\}) = \sum_x \max(p(x),q(x)) = 1 + \|p-q\|_{\TV}$.
\end{theorem}
\begin{proof}
$\max(u,v) = \tfrac{u+v+|u-v|}{2}$ pointwise; sum.
\end{proof}

\begin{theorem}[Strictness]
$C(A) < C(A \cup \{j\})$ iff $\env_A(x) < P_j(x)$ for some $x$.
\end{theorem}

\section{Submodularity in bits}

A general principle is available --- a concave nondecreasing function of a nonnegative monotone submodular set function is submodular --- but $\log_2$ is not finite at $0$, and $C(\emptyset) = 0$ is exactly the value taken on the empty library, so the principle degenerates at the boundary of interest. We prove instead a sharper \emph{multiplicative} inequality, strictly stronger than the additive form whenever the values exceed $1$, which passes through the logarithm cleanly wherever the logarithm is defined.

\begin{theorem}[Multiplicative submodularity]\label{thm:mulsubmod}
$C(A\cup B)\, C(A \cap B) \le C(A)\, C(B)$.
\end{theorem}
\begin{proof}
Write $u = C(A \cup B)$, $i = C(A\cap B)$, $a = C(A)$, $b = C(B)$. Monotonicity gives $0 \le i \le a$ and $i \le b$; Theorem~\ref{thm:submod} gives $u \le a + b - i$. Hence
\[
ab - ui \;\ge\; ab - (a+b-i)i \;=\; (a-i)(b-i)\;\ge\;0. \qedhere
\]
\end{proof}

\begin{theorem}[The price in bits is submodular]\label{thm:bitsubmod}
If $C(A \cap B) > 0$ then
$\price(A \cup B) + \price(A\cap B) \le \price(A) + \price(B)$.
\end{theorem}
\begin{proof}
Monotonicity makes all four values positive, so all logarithms are defined; apply $\log_2$ to Theorem~\ref{thm:mulsubmod} and split the logarithms of products.
\end{proof}

\begin{corollary}
If the pool consists of genuine sources and $A \cap B \ne \emptyset$, the conclusion of Theorem~\ref{thm:bitsubmod} holds, by Proposition~\ref{prop:onele}.
\end{corollary}

\begin{theorem}[The guard is necessary]
Let $X = \{0,1\}$ with the two point masses $P_0 = \delta_0$, $P_1 = \delta_1$, and $A = \{0\}$, $B = \{1\}$. Then $C(A) = C(B) = 1$, $C(A \cup B) = 2$ and $C(A \cap B) = 0$, so the bit-level inequality reads $1 + \log_2 0 \le 0$ and fails for any real-valued convention $\log_2 0 = 0$; it holds only under the extended convention $\log_2 0 = -\infty$.
\end{theorem}

Two libraries with nothing in common satisfy no bit-level submodularity constraint, because a library of zero models has no meaningful price. Implementations working with real numbers must carry the guard.

\section{Greedy library design}

\begin{definition}[Greedy run]
Libraries $A_0, A_1, \ldots$ form a \emph{greedy run} if $A_0 = \emptyset$; each $A_{k+1} = A_k \cup \{j_k\}$; and each step is optimal: $C(A_k \cup \{j\}) \le C(A_{k+1})$ for all $j \in \iota$.
\end{definition}

\begin{proposition}
A greedy run satisfies $|A_k| \le k$, so comparing $A_n$ with libraries of size $n$ compares equal budgets.
\end{proposition}

\begin{lemma}[One greedy step earns its share]\label{lem:step}
For any library $A$ and nonempty $B$ with $|B| = n$ there is $j \in B$ with $\Delta(j\mid A) \ge \bigl(C(B)-C(A)\bigr)/n$.
\end{lemma}
\begin{proof}
By monotonicity and Theorem~\ref{thm:cover},
$C(B) - C(A) \le C(A\cup B) - C(A) \le \sum_{j\in B}\Delta(j\mid A)$;
a sum of $n$ terms bounded below by $n \cdot \frac{C(B)-C(A)}{n}$ has a term at least $\frac{C(B)-C(A)}{n}$.
\end{proof}

\begin{theorem}[Geometric decay of the gap]\label{thm:gap}
For a greedy run $(A_k)$ and nonempty $B$ with $|B| = n$, and every $k \ge 0$,
\[
C(B) - C(A_k) \le \Bigl(1 - \tfrac1n\Bigr)^{k} C(B).
\]
\end{theorem}
\begin{proof}
Induction on $k$. For $k=0$, $C(A_0)=0$. For the step, Lemma~\ref{lem:step} and greediness give $C(A_{k+1}) - C(A_k) \ge \frac{C(B)-C(A_k)}{n}$, so $C(B)-C(A_{k+1}) \le (1-\frac1n)(C(B)-C(A_k))$; multiply the inductive bound by $1-\frac1n \ge 0$.
\end{proof}

\begin{lemma}
$(1-\tfrac1n)^n \le e^{-1}$ for every integer $n \ge 1$.
\end{lemma}
\begin{proof}
$1+t \le e^t$ at $t = -1/n$ gives $0 \le 1-\frac1n \le e^{-1/n}$; raise to the $n$-th power.
\end{proof}

\begin{theorem}[Greedy design is $(1-1/e)$-optimal]\label{thm:greedy}
For a greedy run $(A_k)$ and any nonempty library $B$ with $n = |B|$,
\[
C(A_n) \ \ge\ \bigl(1 - e^{-1}\bigr) C(B) \ \approx\ 0.6321\, C(B),
\]
in particular when $B$ maximises $C$ among libraries of size $n$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:gap} at $k=n$, the previous lemma, and $C(B) \ge 0$.
\end{proof}

\begin{theorem}[Greedy runs exist]
For a finite nonempty pool, the canonical sequence $A_0 = \emptyset$, $A_{k+1} = A_k \cup \{j_k\}$ with $j_k \in \arg\max_j C(A_k \cup \{j\})$ is a greedy run.
\end{theorem}

\begin{theorem}[The guarantee in bits]
If the pool consists of genuine sources and $n = |B| \ge 1$, the canonical greedy library satisfies
\[
\price(A_n) \ \ge\ \price(B) - \log_2 \frac{e}{e-1}, \qquad \log_2\frac{e}{e-1} = 0.6617\ldots < 0.67 .
\]
\end{theorem}
\begin{proof}
$C(B) \ge 1 > 0$ by Proposition~\ref{prop:onele} and $1 - e^{-1} > 0$; apply $\log_2$ to Theorem~\ref{thm:greedy} and expand the logarithm of the product.
\end{proof}

\section{Algorithms and complexity}

Let $m = |\iota|$, $N = |X|$ and $n$ the budget.

\emph{Envelope maintenance.} Keep the envelope as an array $e \in \mathbb R^N$, initially $0$; inserting model $j$ replaces $e$ by the componentwise $\max(e, P_j)$ in $O(N)$ time, and $C(A) = \sum_x e(x)$ is maintained incrementally.

\emph{Marginal value.} By Theorem~\ref{thm:libmarg}, $\Delta(j \mid A) = \sum_x (P_j(x)-e(x))^{+}$: a single $O(N)$ pass per candidate, with no optimisation, inversion or sampling anywhere.

\emph{Greedy selection.} $O(mN)$ per round, $O(nmN)$ in total --- the cost of reading the pool $n$ times.

\emph{Lazy greedy.} Diminishing returns (Theorem~\ref{thm:dim}) licenses lazy evaluation: keep candidates in a max-heap keyed by their last computed marginal, which upper-bounds the current one; pop, recompute, and accept if it still tops the heap. The output equals that of plain greedy, hence inherits the $(1-1/e)$ guarantee, while the number of marginal evaluations drops substantially --- reductions of $40\%$ to $67\%$ on random pools of a few hundred models, growing with the pool size.

\begin{verbatim}
input:  pool P[1..m] of nonnegative vectors of length N; budget n
output: library A of size <= n
A <- empty;  e <- zero vector of length N
repeat n times:
    best_j <- none;  best_gain <- 0
    for j not in A:
        gain <- sum over x of max(P[j][x] - e[x], 0)
        if gain > best_gain: best_gain <- gain; best_j <- j
    if best_j is none: break        # no model beats the envelope
    A <- A + {best_j};  e <- componentwise max(e, P[best_j])
return A, sum(e)                    # price factor C(A); price = log2 C(A)
\end{verbatim}

\section{A worked pool}

Take $X = \{a_0,a_1,a_2\}$ and the pool

